// PL-60: ZIP64 at the offset boundary, from generated bytes (zip64-test-support.ts); the size boundary is in
// export-zip64-size.test.ts.
import { describe, expect, it } from "vitest";

import { exportGenerated, MAX32 } from "./zip64-test-support.ts";

/** Bytes before the second entry's local header: the first's header and name ("a"), its bytes, its data descriptor. */
const FIRST_OVERHEAD = 30 + 1 + 16;

describe("PL-60: ZIP64 where an offset needs it", () => {
  it("writes the offset of a local header at 0xFFFFFFFE without ZIP64", async () => {
    const read = await exportGenerated([
      { path: "a", size: MAX32 - 1 - FIRST_OVERHEAD },
      { path: "b", size: 1 },
      { path: "index.html", size: 10 },
    ]);
    expect(read.offsets[1]).toBe(MAX32 - 1);
    expect(read.entries.map((entry) => entry.zip64)).toEqual([false, false, true]);
    expect(read.zip64).toBe(true);
  }, 120_000);

  it("writes the offset of a local header at 0xFFFFFFFF with ZIP64", async () => {
    const read = await exportGenerated([
      { path: "a", size: MAX32 - FIRST_OVERHEAD },
      { path: "b", size: 1 },
      { path: "index.html", size: 10 },
    ]);
    expect(read.offsets[1]).toBe(MAX32);
    expect(read.entries.map((entry) => entry.zip64)).toEqual([false, true, true]);
    expect(read.zip64).toBe(true);
  }, 120_000);
});
